    },
    {
      "item_code": "S10_INCOMPAT",
      "title_raw": "다. 피해야 할 물질",
      "start": "p8:L13",
      "end": "p8:L14"
    },
    {
      "item_code": "S10_DECOMP",
      "title_raw": "라. 분해시 생성되는 유해물질",
      "start": "p8:L15",
      "end": "p8:L18"
    }
  ],
  "extras": [
    {
      "after_item": "S10_END",
      "title_raw": "가. 화학적 안정성 및 유해 반응의 가능성",
      "reason": "필드없음",
      "statements": [
        {
          "value": "고온에서 분해되어 독성가스를 생성할 수 있음.",
          "line": "p7:L26"
        },
        {
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음.",
          "line": "p7:L27"
        },
        {
          "value": "화재시 자극성, 독성 가스를 발생할 수 있음.",
          "line": "p7:L28"
        },
        {
          "value": "가열시 용기가 폭발할 수 있음.",
          "line": "p7:L29"
        },
        {
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험.",
          "line": "p7:L30"
        },
        {
          "value": "공기와 폭발성 혼합물을 형성함.",
          "line": "p8:L1"
        },
        {
          "value": "극인화성.",
          "line": "p8:L2"
        },
        {
          "value": "열, 스파크, 화염에 의해 쉽게 점화함.",
          "line": "p8:L3"
        },
        {
          "value": "일부는 탈 수 있으나 급격하게 연소하지 않음",
          "line": "p8:L4"
        },
        {
          "value": "증기는 점화원까지 이동하여 역화(flash back)할 수 있음.",
          "line": "p8:L5"
        },
        {
          "value": "실레인(실리콘 수소화물)은 공기 중에서 자연점화함.",
          "line": "p8:L6"
        },
        {
          "value": "일부 물질은 고농도로 흡입시 자극적일 수 있음.",
          "line": "p8:L7"
        },
        {
          "value": "증기는 자각 없이 현기증 또는 질식을 유발할 수 있음.",
          "line": "p8:L8"
        }
      ],
      "line": "p7:L25"
    },
    {
      "after_item": "S10_STABILITY",
      "title_raw": "나. 피해야 할 조건",
      "reason": "필드없음",
      "statements": [
        {
          "value": "열, 오염, 스파크, 화염 등 점화원.",
          "line": "p8:L10"
        },
        {
          "value": "열.",
          "line": "p8:L11"
        },
        {
          "value": "열, 오염.",
          "line": "p8:L12"
        }
      ],
      "line": "p8:L9"
    },
    {
      "after_item": "S10_CONDITIONS",
      "title_raw": "다. 피해야 할 물질",
      "reason": "필드없음",
      "statements": [
        {
          "value": "가연성 물질, 환원성 물질.",
          "line": "p8:L14"
        }
      ],
      "line": "p8:L13"
    }
  ]
}

